import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Frontend author verification","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/verification.md","filePath":"frontend/verification.md"}'),o={name:"frontend/verification.md"};function i(s,e,d,c,p,l){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="frontend-author-verification" tabindex="-1">Frontend author verification <a class="header-anchor" href="#frontend-author-verification" aria-label="Permalink to “Frontend author verification”">​</a></h1><p>Review date: <strong>2026-10-27</strong>. <strong>All learner practice remains outstanding.</strong> Commands ran in isolated temporary copies; root package scripts, submission templates and <code>src/tests</code> were not changed.</p><h2 id="executed-source-and-behavior-checks" tabindex="-1">Executed source and behavior checks <a class="header-anchor" href="#executed-source-and-behavior-checks" aria-label="Permalink to “Executed source and behavior checks”">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>Actual result</th><th>Limit</th></tr></thead><tbody><tr><td>Documentation</td><td>VitePress 2.0.0-alpha.12 production build passed after each early batch; final navigation build and rendered checks recorded in the progress report</td><td>Existing large-chunk warning; does not build React/Next applications</td></tr><tr><td>JavaScript</td><td>Node 24.18.0 runner passed bindings/this, independent closures, nested microtask order, normal completion and repeated disposal</td><td>Node scheduling output is not painted-frame evidence</td></tr><tr><td>TypeScript starter</td><td>TypeScript 5.9.3 strict/noUncheckedIndexedAccess/exactOptionalPropertyTypes passed retained contracts/check, keyed generic and offline-draft source; P-330 runtime assertions passed</td><td>Native IndexedDB lifecycle and real HTTP endpoint not established</td></tr><tr><td>React source</td><td>Actual development and production esbuild bundles; strict compiler checks for demo, composition and all extracted form integrations</td><td>Separate design-system CSS bundling and full private application remain consumer integration</td></tr><tr><td>React reference checks</td><td>Calendar validity, wizard transitions/duplicate guard, monotonic projection, duplicate tab identities and save-response identity/version passed</td><td>Save HTTP mocked; no database write</td></tr><tr><td>Component testing</td><td>Vitest 5.0.5/JSDOM 30.1.3: 3 retained SaveButton tests passed; separate strict typecheck passed</td><td>Simulated DOM/promise handling, not native announcement/layout</td></tr><tr><td>Bounded table</td><td>6 retained Vitest/JSDOM tests passed; separate strict compiler check passed</td><td>Deferred adapter; no real cursor/snapshot/tenant API or measured latency</td></tr><tr><td>Pure Next input boundary</td><td>JSON/content-type/UTF8/byte-limit/deadline and reader cancellation checks passed; mutation parser rejects invalid/extra input</td><td>No auth/session/SQL integration</td></tr><tr><td>Design contracts</td><td>Native Button negative type fixtures and token determinism/missing-key/unknown-alias/invalid-color checks passed</td><td>No measured contrast, Storybook approval or theme hydration result</td></tr><tr><td>Next public fixture</td><td>Next.js 16.4.3 production build/start and TypeScript checks passed; /courses prerendered, /courses/[id] request-rendered</td><td>Fixed public data; no cache-freshness or auth-provider/DB/deployment integration inferred</td></tr></tbody></table><p>The React integration dependency set resolves to React 19.3.0, React Hook Form 7.91.0, resolver 5.9.2, TanStack Query 5.105.0 and Zod 4.6.7. Exact manifests/locks live with the reference collections. Next explicitly uses cacheComponents:false; current generator defaults can differ.</p><h2 id="native-browser-observations" tabindex="-1">Native browser observations <a class="header-anchor" href="#native-browser-observations" aria-label="Permalink to “Native browser observations”">​</a></h2><p>Environment: <strong>Chrome 156.0.8078.48 on macOS, headless</strong>, driven by Playwright 1.58.2 against owned loopback servers. These are desktop-browser runs with viewport changes, not physical mobile-device tests. Screenshots were captured for visual inspection; no approved regression baseline is implied.</p><ul><li><strong>Public search, JavaScript on and off, 320×640:</strong> Tab reached skip link then labeled search field; Enter returned a real course-note link. No page-width horizontal overflow. Failed JSON retained the input and keyboard activation of regular-results fallback opened server HTML. Blocking the enhancement module preserved the native GET path. Empty/duplicate query parameters returned 400; echoed markup was escaped. No page exceptions.</li><li><strong>React reference, development StrictMode and production:</strong> replacement queue produced 1 and two functional updates then produced 3; edited B stayed with B after reversal. Resolving B before A kept B even though the controlled adapter ignored abort. One live request owner remained after replacement; unmount left zero. Tabs supported ArrowRight (skipping disabled), Home/End and Tab to the panel. Space activated the native action.</li><li><strong>React dialog:</strong> named modal opened with heading focus; the checked light-DOM focus cycle contained Tab/Shift+Tab, Escape closed and restored the trigger. The initial check exposed Tab leaving the document after the last native control; the bounded edge-cycle correction passed retest. Arbitrary shadow/iframe/positive-tabindex content is outside this primitive&#39;s contract.</li><li><strong>React wizard:</strong> invalid reversed dates kept the schedule step and focused the invalid end field; Back retained entered dates; the local fake save moved focus to its surviving completion region. The fake save persists nothing. At 320px, the reference page had no page-width overflow. No page exceptions.</li><li><strong>Next public app:</strong> with JavaScript disabled, native detail links remained usable via keyboard. Hydrated filter selected the expected course; keyboard detail/return links worked. A missing detail displayed the recovery page with an observed <strong>HTTP 200 streamed response</strong>, consistent with the lesson&#39;s status warning; Browse courses recovered. At 320px there was no page-width overflow. No page exceptions.</li></ul><p>Retained <a href="./../workbench/frontend/verification/">author browser scripts</a> reproduce these bounded scenarios. The original authored Chromium/Firefox/WebKit/screenshot suite is separate and was not run across all engines or given an approved snapshot baseline.</p><h2 id="documentation-navigation-and-visual-inspection" tabindex="-1">Documentation navigation and visual inspection <a class="header-anchor" href="#documentation-navigation-and-visual-inspection" aria-label="Permalink to “Documentation navigation and visual inspection”">​</a></h2><p>Rendered local-link/anchor check across the new path/practice/workbench and related Senior Growth frontend/architecture pages: <strong>zero broken destinations or anchors</strong>. Compared 104 existing changed rendered pages with the pre-frontend site: <strong>no previous IDs lost</strong>. The original Notes anchors remain compatibility targets in the reordered indexes.</p><p>Nine representative documentation pages were opened at 1360×960, including an existing semantics page and rendered TypeScript starter. Both new Mermaid process diagrams rendered without errors. Coverage, browser, React, Next, practice and workbench pages at 390×844 had no page-width overflow or page exceptions. Captured desktop/mobile documentation and reference-app screenshots were visually inspected for readable content and wrapping; these are observations from the declared environment, not baseline approval or physical-device testing.</p><p>The source sweep parsed 47 TypeScript/TSX examples and 14 JavaScript files without syntax errors; syntax checks are not substitutes for the strict/build/behavior checks listed above. Generated declarations were excluded from transpilation. Protected Node/CS/applied-AI directories, the existing Node example, original historical reports and prior progress body were preserved against the start-of-frontend snapshot.</p><h2 id="unperformed-checks-and-optional-extensions" tabindex="-1">Unperformed checks and optional extensions <a class="header-anchor" href="#unperformed-checks-and-optional-extensions" aria-label="Permalink to “Unperformed checks and optional extensions”">​</a></h2><p>No screen-reader announcement/task test, 200% text enlargement, 400% page zoom, real device, real Safari/Firefox/WebKit matrix, forced-colors/contrast certification, touch keyboard, service-worker install/update, native IndexedDB blocked-upgrade test or product-wide WCAG audit is claimed. These are explicit practice/support-matrix requirements.</p><p>No full P-328/P-329/P-330 application, private authentication provider/session deployment, PostgreSQL mutation-concurrency integration, real cache invalidation across instances, HTTPS cookie/ingress test, social-image/font binary check, Storybook baseline approval, live telemetry or performance improvement measurement was performed in this batch. Security fragments are worked boundaries requiring integration, not a ready login product. No paid service, remote push, published workflow or external action was used.</p><p>See <a href="./coverage-map.html">coverage and scope</a>, <a href="./">reading order</a> and <a href="./../practice/frontend/">separate practice</a>. Material completion does not establish learner mastery or a tested production deployment.</p>',17)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
